package password

import "testing"

func TestFormatCompatibility(t *testing.T) {
	const pw = "fixture password — correct horse"
	// The previous independent implementations generated the Argon2id
	// fixtures and verified them at their production defaults. The bcrypt
	// fixtures were generated by x/crypto and verified by the old readers.
	tests := []struct {
		name, hash string
		rehash     bool
	}{
		{"argon2id m=64MiB t=3 p=4 (current default) #1", "$argon2id$v=19$m=65536,t=3,p=4$Jd2b9jKaPgzXZeNBB6tUVg$H20XSz/vaDCwZF1SjqH0HucFSM8NIv40KyMF73CKxgc", false},
		{"argon2id m=64MiB t=3 p=4 (current default) #2", "$argon2id$v=19$m=65536,t=3,p=4$NPucRrrft/OnzSx3mEgVdw$kAGojMlUl2xP7XKn4MztL/ux9agLwhd80fK9Sd87kLg", false},
		{"argon2id m=64MiB t=3 p=4 (current default) #3", "$argon2id$v=19$m=65536,t=3,p=4$xJLadhT3TbwYmLm+YFqusQ$cfjRw0dF9Xr+0rb0PcjZHc9oOl1Uu0neXlvoGc3hhhU", false},
		{"argon2id m=64MiB t=3 p=4 (current default) #4", "$argon2id$v=19$m=65536,t=3,p=4$253gtlqDjxvMlnUURi5WNA$b39TMpNhV9MFYWncuAhvG5K/VzdQ7RG+3ax4fXD0vYU", false},
		{"argon2id m=64MiB t=3 p=2 (legacy) #1", "$argon2id$v=19$m=65536,t=3,p=2$nZssXRW4AUmAKmen7M8Iow$eZG7KVtFczy875iUCRXR/V86PrFfPJ77er+SqhdO9Q8", true},
		{"argon2id m=64MiB t=3 p=2 (legacy) #2", "$argon2id$v=19$m=65536,t=3,p=2$UlSFodtdnKFi8oCFymhnFA$5sqEP9o2Gew2SutiLbRWKwGBzf0r+VwqFvt4fYSBvxY", true},
		{"argon2id m=64MiB t=3 p=2 (legacy) #3", "$argon2id$v=19$m=65536,t=3,p=2$zp6s2YMdLYDfcFxLucupKw$9QxwJ/K5PR1ZnYI7cuuAD7IXOWDu/dj8T/P8JCJB1+M", true},
		{"argon2id m=64MiB t=2 p=1 (legacy)", "$argon2id$v=19$m=65536,t=2,p=1$L4JbaOx9hD5JNc1QXu+HiA$lvuXlFFqT1PzYcgRsgV+MLCOBiLdn37udXlW6AEIy90", true},
		{"bcrypt $2a$ cost 10 (legacy) #1", "$2a$10$twjQA8BMDdFuHP3afXoWe.PWv/NGS/A2zpHSrgDmWAVc/fzuPmJ66", true},
		{"bcrypt $2a$ cost 10 (legacy) #2", "$2a$10$enFzWumMIWCNHULrn1l39eSZI7xFWKYtW4B/wbjObDBEUgNrNdYC6", true},
	}
	// Check write-time acceptance too: existing credentials must survive
	// both the format guard and the verifier during migration.
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if err := Validate(tc.hash); err != nil {
				t.Fatal(err)
			}
			assertCheck(t, tc.hash, pw, true, tc.rehash)
			assertCheck(t, tc.hash, pw+"!", false, false)
		})
	}
}
